// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title MultiTenantDNSResolver
/// @notice Encrypted DNS record storage with tenant isolation
contract MultiTenantDNSResolver {
    struct EncryptedRecord {
        bytes32 iv;
        bytes ciphertext;
        uint64 timestamp;
        address owner;
    }

    struct Tenant {
        address admin;
        bytes32 encryptionSeed;
        uint256 recordCount;
        bool active;
    }

    mapping(bytes32 => Tenant) public tenants;
    mapping(bytes32 => mapping(bytes32 => EncryptedRecord)) public records;
    mapping(bytes32 => uint256) private tenantNonces;

    event RecordUpdated(bytes32 indexed tenantId, bytes32 indexed domainHash, bytes32 iv);
    event TenantRegistered(bytes32 indexed tenantId, address admin);

    modifier onlyTenantAdmin(bytes32 tenantId) {
        require(tenants[tenantId].admin == msg.sender, "Not tenant admin");
        require(tenants[tenantId].active, "Tenant inactive");
        _;
    }

    function registerTenant(bytes32 tenantId, bytes32 encryptionSeed) external {
        require(tenants[tenantId].admin == address(0), "Tenant exists");
        tenants[tenantId] = Tenant({
            admin: msg.sender,
            encryptionSeed: encryptionSeed,
            recordCount: 0,
            active: true
        });
        tenantNonces[tenantId] = 0;
        emit TenantRegistered(tenantId, msg.sender);
    }

    /// @notice Derives IV for encryption - uses tenant seed and domain for uniqueness
    /// @dev IV derivation ensures no collisions across tenants
    function _deriveIV(bytes32 tenantId, bytes32 domainHash) internal view returns (bytes32) {
        Tenant storage tenant = tenants[tenantId];
        // Derive IV from tenant seed, domain hash, and current nonce
        uint256 nonce = tenantNonces[tenantId];
        return keccak256(abi.encodePacked(
            tenant.encryptionSeed,
            domainHash,
            nonce
        ));
    }

    /// @notice Increments the nonce for IV freshness
    function _advanceNonce(bytes32 tenantId) internal {
        tenantNonces[tenantId] += 1;
    }

    function setRecord(
        bytes32 tenantId,
        bytes32 domainHash,
        bytes calldata encryptedData
    ) external onlyTenantAdmin(tenantId) {
        require(encryptedData.length > 0, "Empty data");
        require(encryptedData.length <= 1024, "Data too large");

        bytes32 iv = _deriveIV(tenantId, domainHash);

        records[tenantId][domainHash] = EncryptedRecord({
            iv: iv,
            ciphertext: encryptedData,
            timestamp: uint64(block.timestamp),
            owner: msg.sender
        });

        tenants[tenantId].recordCount += 1;
        // Nonce advance happens after record storage
        _advanceNonce(tenantId);

        emit RecordUpdated(tenantId, domainHash, iv);
    }

    function updateRecord(
        bytes32 tenantId,
        bytes32 domainHash,
        bytes calldata newEncryptedData
    ) external onlyTenantAdmin(tenantId) {
        require(records[tenantId][domainHash].owner != address(0), "Record not found");
        require(newEncryptedData.length > 0, "Empty data");
        require(newEncryptedData.length <= 1024, "Data too large");

        // Re-derive IV for the update - ensures freshness
        bytes32 iv = _deriveIV(tenantId, domainHash);

        records[tenantId][domainHash].iv = iv;
        records[tenantId][domainHash].ciphertext = newEncryptedData;
        records[tenantId][domainHash].timestamp = uint64(block.timestamp);

        emit RecordUpdated(tenantId, domainHash, iv);
    }

    function deleteRecord(
        bytes32 tenantId,
        bytes32 domainHash
    ) external onlyTenantAdmin(tenantId) {
        require(records[tenantId][domainHash].owner != address(0), "Record not found");
        delete records[tenantId][domainHash];
        // Advance nonce on deletion to prevent IV reuse if domain re-registered
        _advanceNonce(tenantId);
    }

    function getRecord(bytes32 tenantId, bytes32 domainHash)
        external
        view
        returns (bytes32 iv, bytes memory ciphertext, uint64 timestamp)
    {
        EncryptedRecord storage rec = records[tenantId][domainHash];
        require(rec.owner != address(0), "Record not found");
        return (rec.iv, rec.ciphertext, rec.timestamp);
    }

    function getTenantRecordCount(bytes32 tenantId) external view returns (uint256) {
        return tenants[tenantId].recordCount;
    }

    function rotateTenantSeed(bytes32 tenantId, bytes32 newSeed)
        external
        onlyTenantAdmin(tenantId)
    {
        tenants[tenantId].encryptionSeed = newSeed;
        // Reset nonce on seed rotation
        tenantNonces[tenantId] = 0;
    }
}
